<div class="ph sms" data-pv="sms"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($site)) ?></span><span><?= h(strtoupper(mb_substr($site, 0, 11))) ?></span></div><div class="ph-bd"><span class="ph-day">Text Message · Today</span><div class="bub" data-pv-m style="white-space:pre-line"></div></div></div></div>
<div class="ph em" data-pv="email"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($site)) ?></span><span class="col"><span><?= h($site) ?></span><span style="font:400 11px Figtree;color:#777">to <?= h($d['sample']['email']) ?></span></span></div><div class="ph-bd"><div class="card"><b class="s" data-pv-s></b><span data-pv-m style="white-space:pre-line"></span><span class="cta">Open my account</span></div></div></div></div>
<span class="mut" id="bc-noch" hidden>Pick at least one channel.</span>
</div></aside></div>
<script>
(function(){
  var AJ = 'ajax/tools/push_notifications_ajax.php', R = <?= json_encode($rt) ?>, type = <?= json_encode($d['type']) ?>, media = '', $ = function(i){ return document.getElementById(i); };
  function chans(){ return Array.prototype.filter.call(document.querySelectorAll('[data-ch]'), function(b){ return b.classList.contains('on'); }).map(function(b){ return b.getAttribute('data-ch'); }); }
  function base(){ return { notification_type: type, user_id: $('bc-uid').value, consolidation_id: $('bc-cid').value, channels: chans().join(','), subject: $('bc-subj').value, message: $('bc-msg').value, media_file: media }; }
  function view(){
    document.querySelectorAll('#bc-type button').forEach(function(b){ var on = b.getAttribute('data-v') === type; b.classList.toggle('on', on); if (on) $('bc-hint').textContent = b.getAttribute('data-hint'); });
    ['broadcast', 'single_user', 'consolidation'].forEach(function(k){ $('bc-to-' + k).style.display = k === type ? '' : 'none'; });
    var c = chans(); document.querySelectorAll('[data-pv]').forEach(function(p){ p.style.display = c.indexOf(p.getAttribute('data-pv')) >= 0 ? '' : 'none'; }); $('bc-noch').hidden = c.length > 0;
    var m = $('bc-msg').value, s = $('bc-subj').value; document.querySelectorAll('[data-pv-m]').forEach(function(x){ x.textContent = m || 'Your message appears here.'; }); document.querySelectorAll('[data-pv-s]').forEach(function(x){ x.textContent = s; });
    var n = m.length; $('bc-count').textContent = n + ' characters · ' + Math.max(1, Math.ceil(n / 153)) + ' SMS part' + (n > 153 ? 's' : '');
  }
  var et; function estimate(){ clearTimeout(et); et = setTimeout(function(){ var p = base(); p.action = 'estimate'; SL.post(AJ, p).then(function(j){ var a = j.audience || { total: 0, with_phone: 0, with_email: 0 }, c = chans(), cost = 0, bits = [];
    var parts = R.sms_per_part ? Math.max(1, Math.ceil($('bc-msg').value.length / 153)) : 1;
    if (c.indexOf('whatsapp') >= 0) { cost += a.with_phone * R.whatsapp; bits.push(a.with_phone + ' WhatsApp'); } if (c.indexOf('sms') >= 0) { cost += a.with_phone * R.sms * parts; bits.push(a.with_phone + ' SMS'); } if (c.indexOf('email') >= 0) { cost += a.with_email * R.email; bits.push(a.with_email + ' e-mails'); }
    $('bc-reach').textContent = a.total + ' recipient(s) · ' + a.with_phone + ' with a phone · ' + a.with_email + ' with an e-mail. Customers without a number or address are skipped and logged.';
    $('bc-cost').textContent = R.available ? 'About ' + R.currency + ' ' + cost.toFixed(2) : 'Cost: set unit prices in Message costs'; $('bc-costb').textContent = bits.join(' · '); $('bc-send').querySelector('span').textContent = 'Send to ' + a.total; }); }, 250); }
  document.addEventListener('click', function(e){ var b;
    if ((b = e.target.closest('#bc-type button'))) { type = b.getAttribute('data-v'); view(); estimate(); }
    else if ((b = e.target.closest('[data-ch]'))) { var on = !b.classList.contains('on'); b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); b.querySelector('.sl-chk').classList.toggle('on', on); view(); estimate(); }
    else if ((b = e.target.closest('[data-bc-pick]'))) { $('bc-uid').value = b.getAttribute('data-bc-pick'); $('bc-q').value = b.getAttribute('data-name'); $('bc-sug').innerHTML = ''; estimate(); }
  });
  var st; $('bc-q').addEventListener('input', function(){ var q = this.value; $('bc-uid').value = 0; clearTimeout(st); st = setTimeout(function(){ SL.post('ajax/sl/compose_ajax.php', { op: 'search', q: q }).then(function(j){ $('bc-sug').innerHTML = (j.items || []).map(function(it){ var d = document.createElement('div'); d.textContent = it.name; var n = d.innerHTML; d.textContent = it.sub; return '<button type="button" class="row g8 sm" style="text-align:left;padding:8px 10px;border:0;border-bottom:1px solid var(--line);background:var(--card);cursor:pointer" data-bc-pick="' + it.id + '" data-name="' + n.replace(/"/g, '&quot;') + '"><b class="fw5">' + n + '</b><span class="mut">' + d.innerHTML + '</span></button>'; }).join(''); }); }, 200); });
  ['bc-subj', 'bc-msg'].forEach(function(i){ $(i).addEventListener('input', function(){ view(); if (i === 'bc-msg') estimate(); }); }); $('bc-cid').addEventListener('change', estimate);
  $('bc-file').addEventListener('change', function(){ var f = this.files[0]; if (!f) return; var fd = new FormData(); fd.append('media', f); $('bc-att').textContent = 'uploading…'; SL.post('ajax/tools/push_media_upload_ajax.php', fd).then(function(j){ if (j.success) { media = j.file; $('bc-att').textContent = f.name; document.querySelector('[data-pv-att]').hidden = false; document.querySelector('[data-pv-attn]').textContent = f.name; } else { $('bc-att').textContent = 'none'; SL.toast(j.message || 'Upload failed', true); } }); });
  $('bc-send').addEventListener('click', function(){ if (!chans().length) { SL.toast('Pick at least one channel', true); return; } if (!confirm('Send this push now?')) return; var btn = this, t = { s: 0, k: 0, f: 0, n: 0 }; btn.disabled = true; $('bc-prog').hidden = false;
    (function step(after, batch){ var p = base(); p.after_id = after; p.batch_id = batch || ''; SL.post(AJ, p).then(function(j){ if (!j.success) { var er = j.errors ? Object.values(j.errors).join(' ') : (j.message || 'Not sent'); SL.toast(er, true); btn.disabled = false; return; } var s = j.summary;
      ['whatsapp', 'email', 'sms'].forEach(function(c){ t.s += s[c].sent; t.k += s[c].skipped; t.f += s[c].failed; }); t.n += s.recipients; $('bc-s').textContent = t.s; $('bc-k').textContent = t.k; $('bc-f').textContent = t.f; $('bc-n').textContent = t.n + ' / ' + s.total; document.querySelector('.bc-bar i').style.width = Math.round(t.n / Math.max(1, s.total) * 100) + '%'; $('bc-logs').href = 'message_logs.php?batch_id=' + encodeURIComponent(s.batch_id);
      if (s.done) { btn.disabled = false; SL.toast('Push finished: ' + t.s + ' delivered, ' + t.f + ' failed'); } else step(s.next_after_id, s.batch_id); }).catch(function(){ SL.toast('Network error', true); btn.disabled = false; }); })(0, '');
  });
  view(); estimate();
})();
</script>
